			int n = Integer.parseInt(kb.nextLine().trim());	
		
			String s = "                                 ";
			for(int i=0; i<n/2 + 1; i++) {
				out.print(s.substring(0,n/2-i));
				for(int j=0; j<2*i+1; j++)
